# Tests whose result depends on how busy the machine is (they leave a margin of a second or two for a process to be
# stopped), so on a loaded one they fail whatever the code does.
LOAD_SENSITIVE: set[str] = set()


def failed_tests(output: str) -> set[str]:
    """The tests a run reports as failed. Swift Testing prints `✘ Test name() failed`, `✘ Test name(argument:) recorded an issue ...`
    (a parameterized test), `✘ Test "display name" ... failed` and, for one case of a parameterized test, `✘ Test case ... to "display name" failed`."""
    names: set[str] = set()
    for match in re.finditer(r'✘ Test (?:case .*? to "([^"]+)"|(\w+)\([^)]*\)|"([^"]+)")', output):
        names.add(next(group for group in match.groups() if group))
    return names


def tests_for(file: str) -> list[str]:
    """What to hand `swift test` for a mutant of `file`. The files of `Apps/` are compiled into the package only as the `AppModel` target, which no other test target links, so
    the tests of that target are the ones that can notice a change in them; every other file is looked at by the whole suite."""
    return ["--filter", "AppModelTests"] if file.startswith("Apps/") else []


def run_tests(clone: pathlib.Path, only: list[str] = []) -> tuple[str, bool]:
    """`swift test` in the clone: what it printed, and whether it had to be killed for hanging."""
    # Its own session, so that on a hang the test host and every rh it started are stopped together.
    # A run that is killed can be cut inside a multi-byte character (the checkmarks of the test report are three bytes), so what cannot
    # be decoded is replaced and not an error: strict decoding crashed this script on the very hang it is there to report.
    # The tests make their folders in TMPDIR: one of this run's own, so that what a test started and left behind can be found by it afterwards.
    # A mutant that takes away a time limit left a git hanging on a named pipe in such a folder; the test that started it ended, and the git was
    # found twelve hours later, in a process group and session of its own, which the kills below do not reach.
    scratch = clone.parent / "tmp"
    scratch.mkdir(exist_ok=True)
    environment = dict(os.environ, TMPDIR=str(scratch) + "/")
    process = subprocess.Popen(["swift", "test", *only], cwd=clone, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                               text=True, errors="replace", start_new_session=True, env=environment)
    try:
        output, _ = process.communicate(timeout=900)
        return output, False
    except subprocess.TimeoutExpired:
        os.killpg(process.pid, signal.SIGKILL)
        # The test helper that SwiftPM starts is in a process group of its own, so the group above does not reach it: it was found four hours later, orphaned, still holding the
        # clone. Everything in the session goes.
        subprocess.run(["pkill", "-KILL", "-s", str(process.pid)], check=False)
        output, _ = process.communicate()
        return output, True
    finally:
        subprocess.run(["pkill", "-KILL", "-f", str(scratch)], check=False)


KILLERS = ROOT / ".build" / "mutation-killers.json"


def remembered_killers() -> dict[str, list[str]]:
    try:
        return json.loads(KILLERS.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return {}


def remember_killers(name: str, killers: list[str]) -> None:
    """Keeps the tests that killed `name`, for the next run. Only names that `--filter` can find (a function's name, not a display name)."""
    usable = [k for k in killers if re.fullmatch(r"\w+", k)][:8]
    if not usable:
        return
    known = remembered_killers()
    known[name] = usable
    KILLERS.parent.mkdir(parents=True, exist_ok=True)
    KILLERS.write_text(json.dumps(known, indent=1, sort_keys=True), encoding="utf-8")


def real_home_fingerprint() -> dict[str, object]:
    """What a setup that reached the real home would change: the runner script, the command link and the Quick Actions of this account.

    A mutant removes the protection a test is for and runs the test, so a test that expects `rh setup` to be refused can, under a mutant, be the one that
    sets up the real home (once it replaced the real runner script with one that pointed into the throwaway clone). The tests give `rh` a trial home and
    `rh` refuses the real home from a test (`RealHomeGuard`); this notices it if that is not enough.
    """
    home = pathlib.Path(pwd.getpwuid(os.getuid()).pw_dir)
    # Not the folder of the Services itself: its date changes when anything else is installed there, and the run would stop for it.
    watched = [home / "Library/Application Scripts/com.boyugou.righthere.FinderExtension/rh-run", home / ".local/bin/rh"]
    watched += sorted((home / "Library/Services").glob("Right Here*")) if (home / "Library/Services").is_dir() else []
    state: dict[str, object] = {}
    for path in watched:
        try:
            info = path.lstat()
            state[str(path)] = (info.st_mtime_ns, os.readlink(path) if path.is_symlink() else None)
        except OSError:
            state[str(path)] = None
    return state


def main() -> int:
    arguments = sys.argv[1:]
    if arguments == ["--list"]:
        for index, (name, file, _old, _new) in enumerate(MUTANTS):
            print(f"{index:2}  {name}  ({file})")
        return 0
    if arguments == ["--check"]:
        # A line that was changed leaves its entry matching nothing, and a run of two hours skips it: found by a review, a hundred minutes into a run.
        problems = []
        for index, (name, file, old, new) in enumerate(MUTANTS):
            path = ROOT / file
            if not path.exists():
                problems.append(f"[{index}] {file} is not there: {name}")
                continue
            occurrences = path.read_text(encoding="utf-8").count(old)
            if occurrences != 1:
                problems.append(f"[{index}] the pattern for \"{name}\" is in {file} {occurrences} times, not once")
            if old == new:
                problems.append(f"[{index}] the pattern for \"{name}\" is the same as its replacement")
        if problems:
            print("\n".join(problems), file=sys.stderr)
            return 1
        print(f"ok: all {len(MUTANTS)} mutation entries match the tree exactly once")
        return 0
    chosen = {int(a) for a in arguments} if arguments else set(range(len(MUTANTS)))

    problems: list[str] = []
    home_before = real_home_fingerprint()
    with tempfile.TemporaryDirectory(prefix="rh-mutation-") as folder:
        clone = pathlib.Path(folder) / "clone"
        subprocess.run(["git", "clone", "--quiet", "--local", str(ROOT), str(clone)], check=True)
        for index, (name, file, old, new) in enumerate(MUTANTS):
            if index not in chosen:
                continue
            path = clone / file
            original = path.read_text(encoding="utf-8")
            occurrences = original.count(old)
            if occurrences != 1:
                problems.append(f"[{index}] the pattern for \"{name}\" is in {file} {occurrences} times, not once; make it match exactly once")
                print(f"[{index}] SKIPPED: {name}", flush=True)
                continue
            path.write_text(original.replace(old, new, 1), encoding="utf-8")
            started = time.time()
            remembered = remembered_killers().get(name, [])
            try:
                output, hung = "", False
                # The tests that killed this mutant last time first: a few seconds instead of the whole suite. Only a failure of one of them counts.
                if remembered:
                    output, hung = run_tests(clone, ["--filter", "|".join(remembered)])
                    if hung or not (failed_tests(output) & set(remembered)) - LOAD_SENSITIVE:
                        output, hung = "", False
                if not output:
                    # A run in which only a load-sensitive test failed says nothing, so it is tried once more.
                    for _ in range(2):
                        output, hung = run_tests(clone, tests_for(file))
                        if hung or failed_tests(output) - LOAD_SENSITIVE or "\u2718 Test" not in output:
                            break
            finally:
                path.write_text(original, encoding="utf-8")
            home_after = real_home_fingerprint()
            changed = sorted(name_ for name_ in home_before.keys() | home_after.keys() if home_before.get(name_) != home_after.get(name_))
            if changed:
                print(f"[{index}] STOPPED: this mutant (\"{name}\") changed the real home: {', '.join(changed)}.\n"
                      "Repair it with `Right Here.app/Contents/Helpers/rh setup` from the installed app, and make the test that did it give `rh` a trial home (RH_HOME).", file=sys.stderr)
                return 2
            killers = sorted(failed_tests(output) - LOAD_SENSITIVE)
            if hung:
                status = "HUNG"
                problems.append(f"[{index}] the tests hung instead of failing for: {name} ({file})")
            elif killers:
                status = f"killed by {killers[0]}" + (f" and {len(killers) - 1} more" if len(killers) > 1 else "")
                remember_killers(name, killers)
            elif "unexpected signal code" in output:
                # A test host that dies by a signal (SIGPIPE, SIGBUS) is as good as a failed test.
                status = "killed (the test host died)"
            elif "\u2718 Test" in output:
                status = "INCONCLUSIVE"
                problems.append(f"[{index}] only a load-sensitive test failed for: {name} ({file}); run it again when the machine is quieter")
            elif re.search(r"^error: |\.swift:\d+:\d+: error:", output, re.M):
                # A passing test run prints "error:" too (in the names of cases about error messages), so only a
                # compiler diagnostic or SwiftPM's own "error: " line counts.
                status = "DOES NOT COMPILE"
                problems.append(f"[{index}] \"{name}\" does not compile; fix the entry")
            else:
                status = "SURVIVED"
                problems.append(f"[{index}] no test noticed that: {name} ({file})")
            print(f"[{index}] {status} in {time.time() - started:.0f}s: {name}", flush=True)

    if problems:
        print("\n" + "\n".join(problems), file=sys.stderr)
        return 1
    print(f"ok: every one of {len(chosen)} removed protections made a test fail")
    return 0


if __name__ == "__main__":
    sys.exit(main())
